def test_matching_skus_summed():
    """Per spec: matching SKUs should have their counts added together."""
    base = {"A": 3}
    incoming = {"A": 5}
    result = merge_inventory(base, incoming)
    assert result["A"] == 8, f"Expected 3+5=8, got {result['A']}"


def test_base_not_mutated():
    """Per spec: neither input dictionary should be mutated."""
    base = {"A": 3, "B": 2}
    incoming = {"B": 5, "C": 1}
    base_copy = base.copy()
    incoming_copy = incoming.copy()
    merge_inventory(base, incoming)
    assert base == base_copy, "base was mutated"
    assert incoming == incoming_copy, "incoming was mutated"


def test_new_skus_from_incoming():
    """SKUs only in incoming should appear in result."""
    base = {"A": 3}
    incoming = {"B": 5}
    result = merge_inventory(base, incoming)
    assert "B" in result
    assert result["B"] == 5


def test_empty_dictionaries():
    """Empty inputs should return empty result."""
    result = merge_inventory({}, {})
    assert result == {}


def test_empty_base():
    """Empty base with non-empty incoming."""
    result = merge_inventory({}, {"A": 5})
    assert result == {"A": 5}


def test_empty_incoming():
    """Non-empty base with empty incoming."""
    result = merge_inventory({"A": 3}, {})
    assert result == {"A": 3}


def test_non_negative_counts():
    """Counts must be non-negative per spec."""
    try:
        merge_inventory({"A": -1}, {})
        assert False, "Should raise ValueError for negative count"
    except ValueError:
        pass


def test_type_error_for_non_dict():
    """Non-dict inputs should raise TypeError."""
    try:
        merge_inventory("not a dict", {})
        assert False, "Should raise TypeError"
    except TypeError:
        pass


def test_new_result_not_shared_reference():
    """Result should be a new dict, not referencing inputs."""
    base = {"A": 3}
    result = merge_inventory(base, {})
    result["A"] = 999
    assert base["A"] == 3, "Result shares reference with base"


